import{_ as e,c as l,o as a,b0 as r}from"./chunks/framework.BpbtKNwe.js";const i="/aillm-docs/assets/dc2aa1852f74a17081ba8fed11e2ee62.C2HEmH4H.svg",o="/aillm-docs/assets/31a938f25b405ce2878343f54ed27eff.BBhJkbsE.svg",b=JSON.parse('{"title":"LV005-RAG简介","description":null,"frontmatter":{"title":"LV005-RAG简介","date":"2025-11-28T19:54:41.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/llm/rag/126b154d697107ef3e0c0c12","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-28T19:54:41.126Z","fulluuid":"f3e0c0c124794a8eba604aed208c8eb5","useduuid":"f3e0c0c12"}},"headers":[],"relativePath":"sdoc/llm/rag/126b154d697107ef3e0c0c12.md","filePath":"sdoc/05-LLM/06-RAG/LV005-RAG简介.md","lastUpdated":1767430713000}'),d={name:"sdoc/llm/rag/126b154d697107ef3e0c0c12.md"};function n(s,t,p,c,h,u){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="lv005-rag简介" tabindex="-1">LV005-RAG简介 <a class="header-anchor" href="#lv005-rag简介" aria-label="Permalink to &quot;LV005-RAG简介&quot;">​</a></h1><p>RAG 让大模型不再死记硬背，而是像工程师一样“查资料”，随时拥有最新知识。</p><h2 id="一、rag-是什么" tabindex="-1">一、RAG 是什么？ <a class="header-anchor" href="#一、rag-是什么" aria-label="Permalink to &quot;一、RAG 是什么？&quot;">​</a></h2><p>RAG 是 Retrieval-Augmented Generation 的缩写，中文翻译为 &quot;检索增强生成&quot;。它是一种将检索系统和生成式 AI 模型结合的技术方案，主要包含两个核心步骤：</p><p>（1）检索（Retrieval）：根据用户输入的问题，从知识库中检索出相关的文档或信息片段</p><p>（2）生成（Generation）：将检索到的相关信息作为上下文，结合用户问题，让大语言模型生成准确的回答</p><p>检索增强生成（RAG, Retrieval-Augmented Generation）让大语言模型（LLM, Large Language Model）从“内置知识”升级为“可挂载外部知识”。逻辑上，它就像给 LLM 挂上一个“外接硬盘”。</p><p>这种方案既能让模型基于最新的知识作答，又可以提供可溯源的参考依据，有效解决了大语言模型的知识 <strong>时效性</strong> 和 <strong>事实准确性</strong> 问题。</p><p>如果没有 RAG，大模型只能依赖预训练期间学到的知识，无法实时更新。引入 RAG 后，模型可以访问动态数据、私有文档、数据库、日志甚至 API，从一个“语言模型”升级为“知识增强型 Agent”。</p><h2 id="二、为什么需要-rag" tabindex="-1">二、为什么需要 RAG？ <a class="header-anchor" href="#二、为什么需要-rag" aria-label="Permalink to &quot;二、为什么需要 RAG？&quot;">​</a></h2><h3 id="_1-三种问答方案" tabindex="-1">1. 三种问答方案 <a class="header-anchor" href="#_1-三种问答方案" aria-label="Permalink to &quot;1. 三种问答方案&quot;">​</a></h3><p>让我们对比三种问答方案的优缺点，来理解为什么 RAG 是一个更好的选择：</p><p>（1）传统检索式问答 (Retrieval QA)</p><ul><li>✅ 可靠性高：答案直接来自知识库，有明确的来源</li><li>✅ 知识可更新：添加新文档即可更新知识</li><li>❌ 灵活性差：只能返回知识库中已有的内容</li><li>❌ 表达生硬：难以用自然语言组织答案</li></ul><p>（2）纯 LLM 问答</p><ul><li>✅ 表达自然：能用流畅的语言组织答案</li><li>✅ 灵活理解：可以理解各种表达方式的问题</li><li>❌ 知识固化：知识仅限于训练数据，无法及时更新</li><li>❌ 可靠性差：容易产生幻觉，难以验证答案准确性</li></ul><p>（3）RAG 方案</p><ul><li>✅ 可靠且可溯源：答案基于检索到的具体文档</li><li>✅ 知识可更新：可以持续添加新的知识</li><li>✅ 表达自然：利用 LLM 的语言能力组织答案</li><li>✅ 灵活理解：能理解各种形式的问题</li><li>✅ 成本可控：主要消耗在必要的 API 调用上</li></ul><h3 id="_2-解决了什么问题" tabindex="-1">2. 解决了什么问题 <a class="header-anchor" href="#_2-解决了什么问题" aria-label="Permalink to &quot;2. 解决了什么问题&quot;">​</a></h3><p>机器学习模型的本质是“统计压缩”：</p><ul><li>预训练模型 ≈ 一个巨大的概率分布</li><li>内置知识 = 预训练语料当时的状态</li><li>无法实时更新</li><li>无法访问业务知识</li><li>无法访问结构化数据或实时信息</li></ul><p>用工程师的话说：预训练模型就像一个只读的“镜像文件”，生成时无法临时挂载额外的数据卷。RAG 的出现解决了以下问题：</p><ul><li>业务知识经常更新</li><li>模型必须访问实时信息</li><li>私有数据不能放到训练集</li><li>长期来看训练成本太高</li><li>模型无需记住所有内容，只需能“找”</li></ul><p>一句话总结：</p><blockquote><p>RAG = 在大模型前加一层“可检索知识层”，让模型随时看见它未训练过的知识。</p></blockquote><h2 id="三、云原生类比-rag-外挂知识库-是给-llm-的-crd-etcd-controller" tabindex="-1">三、云原生类比：RAG = 外挂知识库，是给 LLM 的“CRD + etcd + Controller” <a class="header-anchor" href="#三、云原生类比-rag-外挂知识库-是给-llm-的-crd-etcd-controller" aria-label="Permalink to &quot;三、云原生类比：RAG = 外挂知识库，是给 LLM 的“CRD + etcd + Controller”&quot;">​</a></h2><p>下表用云原生工程视角类比 RAG 的核心组件：</p><table tabindex="0"><thead><tr><th style="text-align:left;">RAG 组件</th><th style="text-align:left;">云原生类比</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;">Embedding</td><td style="text-align:left;">CRD 索引 / Tag 索引</td><td style="text-align:left;">把文档“结构化”成可检索向量</td></tr><tr><td style="text-align:left;">Vector DB</td><td style="text-align:left;">etcd + 高级检索 + 倒排索引</td><td style="text-align:left;">存储特征向量，实现相似度检索</td></tr><tr><td style="text-align:left;">Retriever</td><td style="text-align:left;">Controller / Informer</td><td style="text-align:left;">根据查询找到最相关的文档</td></tr><tr><td style="text-align:left;">Rerank</td><td style="text-align:left;">精排器 / Admission Webhook</td><td style="text-align:left;">对结果进行更精细排序</td></tr><tr><td style="text-align:left;">Generator (LLM)</td><td style="text-align:left;">业务逻辑层</td><td style="text-align:left;">根据检索结果生成最终答案</td></tr></tbody></table><blockquote><p>RAG = 模型不再全靠自己推理，而是能查询外部“知识 API”。</p></blockquote><h2 id="四、rag-标准流程" tabindex="-1">四、RAG 标准流程 <a class="header-anchor" href="#四、rag-标准流程" aria-label="Permalink to &quot;四、RAG 标准流程&quot;">​</a></h2><p>下图展示了 RAG 的标准工作流程，清晰分为“检索、精排、生成”三大环节：</p><p><img src="'+i+'" alt="图 1: RAG 标准工作流"></p><p>在这个流程中，用户问题经过向量化、检索、精排、上下文构建，最终由 LLM 生成有依据的答案。</p><h2 id="五、rag-的关键技术点" tabindex="-1">五、RAG 的关键技术点 <a class="header-anchor" href="#五、rag-的关键技术点" aria-label="Permalink to &quot;五、RAG 的关键技术点&quot;">​</a></h2><p>RAG 涉及多个关键技术环节，下面逐一介绍。</p><h3 id="_1-embedding-把文本变向量" tabindex="-1">1. Embedding：把文本变向量 <a class="header-anchor" href="#_1-embedding-把文本变向量" aria-label="Permalink to &quot;1. Embedding：把文本变向量&quot;">​</a></h3><p>Embedding 的本质是将任意文本转为语义向量（如 768/1024 维），便于后续的相似度计算。</p><p>工程师类比：</p><blockquote><p>Embedding = 文档的结构化标签，是 CRD 的 schema + index。</p></blockquote><p>注意事项：</p><ul><li>业务场景不同，Embedding 必须调优（如金融、法律、代码）</li><li>选择合适的模型很关键（如 bge-m3、jina-embeddings、GTE、E5 等）</li></ul><h3 id="_2-vector-database-向量数据库" tabindex="-1">2. Vector Database：向量数据库 <a class="header-anchor" href="#_2-vector-database-向量数据库" aria-label="Permalink to &quot;2. Vector Database：向量数据库&quot;">​</a></h3><p>向量数据库用于存储和检索高维向量，支持高效的相似度搜索。</p><p>主要能力包括：</p><ul><li>向量存储</li><li>高维检索（ANN：HNSW、IVF、PQ）</li><li>Meta 数据过滤</li><li>分片、高可用、多租户</li></ul><p>工程类比：</p><blockquote><p>像 etcd，但它不是做一致性，而是做“最近邻搜索”。</p></blockquote><p>常用系统有 Milvus、Qdrant、Weaviate、Elastic + dense_vector、PgVector（Postgres 扩展）等。</p><h3 id="_3-retriever-召回最可能的文档" tabindex="-1">3. Retriever：召回最可能的文档 <a class="header-anchor" href="#_3-retriever-召回最可能的文档" aria-label="Permalink to &quot;3. Retriever：召回最可能的文档&quot;">​</a></h3><p>Retriever 决定用什么方式匹配内容、Top-K 取多少、是否加 metadata filter。</p><p>常见检索策略：</p><ul><li>向量检索</li><li>BM25（关键词检索）</li><li>混合检索（Hybrid Search）</li><li>多路召回</li></ul><p>Hybrid Search（embedding + BM25）是当前最稳的生产方式。</p><h3 id="_4-rerank-精排器" tabindex="-1">4. Rerank：精排器 <a class="header-anchor" href="#_4-rerank-精排器" aria-label="Permalink to &quot;4. Rerank：精排器&quot;">​</a></h3><p>Rerank 负责对召回结果进行更精细的语义相关性排序，通常采用 cross-encoder 结构（如 bge-reranker）。</p><p>工程师类比：</p><blockquote><p>Rerank = Admission Controller，最后把关，决定哪些文档进上下文。</p></blockquote><p>Rerank 能显著提升答案准确度、上下文相关性，并减少幻觉。</p><h3 id="_5-context-assembly-上下文构建" tabindex="-1">5. Context Assembly：上下文构建 <a class="header-anchor" href="#_5-context-assembly-上下文构建" aria-label="Permalink to &quot;5. Context Assembly：上下文构建&quot;">​</a></h3><p>上下文构建常用策略包括 chunk 合并、文档摘要、文档压缩（Distillation）、基于 Token 限制做裁剪。</p><p>工程挑战：</p><ul><li>太长会增加成本和延迟</li><li>太短可能找不到信息</li><li>乱拼接易导致上下文冲突</li></ul><h3 id="_6-llm-generator-有依据地回答" tabindex="-1">6. LLM Generator：有依据地回答 <a class="header-anchor" href="#_6-llm-generator-有依据地回答" aria-label="Permalink to &quot;6. LLM Generator：有依据地回答&quot;">​</a></h3><p>最终，LLM 不再“凭记忆胡思乱想”，而是根据检索到的证据给出 grounded 回答。这是减少幻觉的关键。</p><h2 id="六、rag-全流程架构图" tabindex="-1">六、RAG 全流程架构图 <a class="header-anchor" href="#六、rag-全流程架构图" aria-label="Permalink to &quot;六、RAG 全流程架构图&quot;">​</a></h2><p>下图展示了 RAG 的完整工程架构，适合工程型读者理解各层次关系：</p><p><img src="'+o+'" alt="图 2: RAG 全流程架构图"> 我们将在后续章节深入 RAG 流程的每个环节。</p><h2 id="七、rag-的工程挑战与最佳实践" tabindex="-1">七、RAG 的工程挑战与最佳实践 <a class="header-anchor" href="#七、rag-的工程挑战与最佳实践" aria-label="Permalink to &quot;七、RAG 的工程挑战与最佳实践&quot;">​</a></h2><p>RAG 在实际工程落地中面临诸多挑战，下表总结了常见问题及说明：</p><table tabindex="0"><thead><tr><th style="text-align:left;">问题</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">Chunk 切片策略</td><td style="text-align:left;">太大太小都影响效果</td></tr><tr><td style="text-align:left;">Query 改写</td><td style="text-align:left;">用户提问往往不完整</td></tr><tr><td style="text-align:left;">混合检索</td><td style="text-align:left;">单一方式不稳定</td></tr><tr><td style="text-align:left;">精排</td><td style="text-align:left;">必须带 Rerank，否则召回噪音太大</td></tr><tr><td style="text-align:left;">上下文冲突</td><td style="text-align:left;">多文档合并会互相矛盾</td></tr><tr><td style="text-align:left;">支持长上下文</td><td style="text-align:left;">vLLM、PagedAttention 等技术必备</td></tr></tbody></table><p>这些问题的解决方案和最佳实践我会单独成文深入探讨。</p><h2 id="八、总结" tabindex="-1">八、总结 <a class="header-anchor" href="#八、总结" aria-label="Permalink to &quot;八、总结&quot;">​</a></h2><p>RAG 本质上是给大语言模型（LLM, Large Language Model）加一个“外挂知识库”，让模型能访问外部文档、实时信息和私有数据。</p><p>RAG 的核心流程包括：</p><p>（1）Embedding（把文本向量化）</p><p>（2）Vector DB（存储与检索）</p><p>（3）Retrieve（召回）</p><p>（4）Rerank（精排）</p><p>（5）Context Assembly（构建上下文）</p><p>（6）Generation（生成 grounded 回答）</p><p>工程本质：</p><ul><li>让模型不再死记硬背，而是会“查资料”</li><li>减少幻觉</li><li>降低训练成本</li><li>支持私有数据 / 实时数据</li><li>是 AI 应用的核心基础设施之一</li></ul><blockquote><p>参考资料：</p><p><a href="https://github.com/rag-web-ui/rag-web-ui/blob/main/docs/tutorial/README.md" target="_blank" rel="noreferrer">rag-web-ui/docs/tutorial/README.md at main · rag-web-ui/rag-web-ui</a></p><p><a href="https://jimmysong.io/book/ai-handbook/rag/overview/" target="_blank" rel="noreferrer">RAG：给模型“外挂知识库” | Jimmy Song</a></p></blockquote>',83)])])}const m=e(d,[["render",n]]);export{b as __pageData,m as default};
